def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == 2 and grid[r][c + 1] == 2 and grid[r + 1][c] == 2 and grid[r + 1][c + 1] == 2:
                blocks.append((r, c))
    blocks.sort(key=lambda p: (p[1], p[0]))
    for i, (r, c) in enumerate(blocks):
        color = 8 if (len(blocks) - 1 - i) % 2 == 0 else 2
        for dr in (0, 1):
            for dc in (0, 1):
                out[r + dr][c + dc] = color
    return out
